"""Cart pricing."""

from cart.models import Line, Totals


def _percent_discount(amount: int, percent: int) -> int:
    """Discount of ``percent`` on ``amount``, rounded to a whole cent, halves up."""
    return (amount * percent + 50) // 100


def _parse_coupon(coupon: str) -> tuple[str, int]:
    """Split a coupon into its form name and its whole-number value."""
    if ":" not in coupon:
        raise ValueError(f"invalid coupon: {coupon!r}")
    name, _, value = coupon.partition(":")
    if name not in ("PERCENT", "FIXED") or not value.isdigit():
        raise ValueError(f"invalid coupon: {coupon!r}")
    return name, int(value)


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    subtotal = 0
    bulk_discount = 0
    for line in lines:
        if line.qty < 1:
            raise ValueError("quantity must be at least 1")
        if line.unit_cents < 0:
            raise ValueError("unit price must not be negative")
        line_amount = line.unit_cents * line.qty
        subtotal += line_amount
        if line.qty >= 10:
            bulk_discount += _percent_discount(line_amount, 10)

    coupon_discount = 0
    if coupon is not None:
        name, value = _parse_coupon(coupon)
        remaining = subtotal - bulk_discount
        if name == "PERCENT":
            if not 1 <= value <= 100:
                raise ValueError("percentage must be between 1 and 100")
            coupon_discount = _percent_discount(remaining, value)
        else:
            coupon_discount = min(value, remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal, discount, subtotal - discount)
